(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  const w2x = Math.sin(x*0.035-y*0.01+t*0.5)*8+Math.cos(y*0.028+t*0.4)*6;
  const w2y = Math.cos(x*0.012+y*0.03-t*0.45)*7+Math.sin(y*0.025-x*0.015+t*0.55)*5;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.9],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.8],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.2],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.95],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65)*50, 0.11, 2.1, 1.05],
    [400+Math.cos(t*0.55+2)*60, 200+Math.sin(t*0.75+1)*40, 0.05, 2.8, 0.85]
  ];
  let aS=0, iS=0, mS=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp)*w;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    mS+=Math.cos(d*f*0.5-t*sp*0.3+Math.sin(t*0.2)*2)*w*0.5;
  }
  const n=8; const act=aS/n, inh=iS/n, mod=mS/n;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const spiral2=Math.sin(dist*0.08+ang*2-t*2.2)*Math.cos(dist*0.06-ang*5+t*1.8)*0.25;
  const moire=Math.sin(sx*0.2)*Math.sin(sy*0.2)*Math.sin((sx-sy)*0.15+t*0.7)*0.3;
  const feed=act*0.5-inh*0.35+mod*0.15+bg*0.25+spiral*0.2+spiral2*0.15+moire*0.1;
  const reaction=Math.tanh(feed*2.0);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5+Math.sin(sx*0.08-t*0.3)*Math.cos(sy*0.1+t*0.4)*0.3)*1.5)*0.3;
  const laplacian=Math.sin(sx*0.22+t)*Math.sin(sy*0.22-t*0.5)*Math.cos((sx+sy)*0.18+t*0.8)*0.15;
  const blend=reaction*0.6+cell*0.25+laplacian*0.15;
  const v=blend*0.5+0.5;
  const glow=Math.max(0, Math.sin(reaction*Math.PI*2)*0.5);
  const pal=[[12,8,52],[20,45,98],[18,95,125],[25,155,148],[145,190,80],[210,195,75],[225,145,65],[195,75,72],[145,40,75],[85,25,65],[40,15,55],[12,8,52]];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.85+Math.sin(reaction*Math.PI)*0.15+glow*0.15;
  const edge=Math.abs(reaction)>0.75?1.2:Math.abs(reaction)>0.5?1.08:1.0;
  const sat=1.0+Math.abs(laplacian)*0.3;
  const r0=pal[i][0]+(pal[i+1][0]-pal[i][0])*f;
  const g0=pal[i][1]+(pal[i+1][1]-pal[i][1])*f;
  const b0=pal[i][2]+(pal[i+1][2]-pal[i][2])*f;
  const gray=(r0+g0+b0)/3;
  const sr=gray+(r0-gray)*sat, sg=gray+(g0-gray)*sat, sb=gray+(b0-gray)*sat;
  return [
    Math.min(255,(sr*lum*edge)|0),
    Math.min(255,(sg*lum*edge)|0),
    Math.min(255,(sb*lum*edge)|0)
  ];
}
